const EMOJI_TIPO = {"credito": "💳", "debito": "💳", "conta_corrente": "🏦", "conta": "🏦", "conta_poupanca": "🐷", "conta_investimento": "📈"};
const rows = $input.all().map(i => i.json).filter(r => Object.values(r).some(v => v !== null && v !== undefined));

const contas = rows.map(r => {
  const emoji = EMOJI_TIPO[r.type] || '💼';
  const tipoLabel = r.type === 'credito' ? 'cartão de crédito'
    : r.type === 'debito' ? 'cartão de débito'
    : r.type === 'conta_corrente' || r.type === 'conta' ? 'conta corrente'
    : r.type === 'conta_poupanca' ? 'conta poupança'
    : r.type === 'conta_investimento' ? 'conta investimento'
    : r.type;
  return {
    account_id: r.id,
    name: r.name,
    bank: r.bank,
    type: r.type,
    emoji,
    label: `${emoji} ${r.name} (${tipoLabel}${r.bank ? ' · ' + r.bank : ''})`,
    closing_day: r.closing_day,
    due_day: r.due_day,
    last_four_digits: r.last_four_digits
  };
});

return [{
  json: {
    quantidade: contas.length,
    contas
  }
}];

